import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { STORE_FONTS_CLASS } from '../../../../scripts/build-store-fonts.mjs'

// The theme faces' stylesheet (page weight 2026-11-23): store-fonts.css is generated by scripts/build-store-fonts.mjs and
// fonts.ts names its class. One class, and every face variable the app reads is set by it, or a face silently falls back.
const css = readFileSync(new URL('../store-fonts.css', import.meta.url), 'utf8')
const fontsTs = readFileSync(new URL('../fonts.ts', import.meta.url), 'utf8')

describe('the theme faces\' stylesheet', () => {
  it('fonts.ts gives elements the class the stylesheet defines', () => {
    expect(fontsTs).toContain(`export const STORE_FONT_VARS = '${STORE_FONTS_CLASS}'`)
    expect(css).toMatch(new RegExp(`^\\.${STORE_FONTS_CLASS} \\{`, 'm'))
  })
  it('sets every --font-store-* variable the app reads for these faces', () => {
    const read = new Set<string>()
    for (const f of ['../font-families.ts', '../../../app/base.css']) for (const m of readFileSync(new URL(f, import.meta.url), 'utf8').matchAll(/var\((--font-store-[a-z-]+)/g)) read.add(m[1]!)
    const brandOnly = new Set(['--font-store-mukta', '--font-store-tiro']) // brand-fonts.ts, still next/font
    const set = new Set([...css.matchAll(/^\s*(--font-store-[a-z-]+):/gm)].map((m) => m[1]))
    expect([...read].filter((v) => !brandOnly.has(v) && !set.has(v))).toEqual([])
    expect(set.size).toBe(8)
  })
})
